import 'dart:convert';

/// Mirrors flutter_tools' ToolExit (`final class ToolExit implements Exception`).
class ToolExit implements Exception {
  ToolExit(this.message);
  final String message;
  @override
  String toString() => 'ToolExit: $message';
}

/// Mirrors flutter_tools/lib/src/convert.dart Utf8Decoder (reportErrors: true).
class ToolsUtf8Decoder {
  const ToolsUtf8Decoder({this.reportErrors = true});
  static const Utf8Decoder _systemDecoder = Utf8Decoder(allowMalformed: true);
  final bool reportErrors;

  String convert(List<int> input) {
    final String result = _systemDecoder.convert(input);
    if (reportErrors && result.contains('\u{FFFD}')) {
      throw ToolExit(
        'Bad UTF-8 encoding (U+FFFD; REPLACEMENT CHARACTER) found while '
        'decoding string: $result. ...  The source bytes were:\n$input',
      );
    }
    return result;
  }
}

void main() {
  // 1) Data that legitimately contains U+FFFD (e.g. text received from a server).
  const String text = 'server says: \u{FFFD}';
  final List<int> bytes = utf8.encode(text);
  print('bytes = $bytes'); // [..., 239, 191, 189] — VALID UTF-8

  // Strict decoding succeeds: the bytes are not malformed.
  print(const Utf8Decoder(allowMalformed: false).convert(bytes));

  // 2) Genuinely malformed bytes: a truncated 3-byte sequence.
  const List<int> broken = <int>[0xEF, 0xBF];

  // 3) flutter_tools cannot tell these two apart — both throw.
  for (final MapEntry<String, List<int>> c
      in <String, List<int>>{'valid U+FFFD': bytes, 'truncated': broken}.entries) {
    try {
      print('${c.key}: ${const ToolsUtf8Decoder().convert(c.value)}');
    } on ToolExit catch (e) {
      print('${c.key}: $e');
    }
  }
}


