```dart
import 'dart:async';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

void main() => runApp(const App());

class App extends StatefulWidget {
  const App({super.key});

  @override
  State<App> createState() => _AppState();
}

class _AppState extends State<App> with WidgetsBindingObserver {
  final GlobalKey _boundary = GlobalKey();
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _timer = Timer.periodic(const Duration(seconds: 2), (_) => _readStrip());
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      WidgetsBinding.instance.addPostFrameCallback((_) => _readStrip());
    }
  }

  Future<void> _readStrip() async {
    if (WidgetsBinding.instance.lifecycleState != AppLifecycleState.resumed) return;
    final RenderRepaintBoundary? boundary =
        _boundary.currentContext?.findRenderObject() as RenderRepaintBoundary?;
    final OffsetLayer? layer = boundary?.layer as OffsetLayer?;
    if (boundary == null || layer == null) return;

    // Record the boundary's pictures into a Picture (no Scene), then read 16 columns back.
    final double pixelRatio = 16 / boundary.size.width;
    final ui.PictureRecorder recorder = ui.PictureRecorder();
    final Canvas canvas = Canvas(recorder)..scale(pixelRatio);
    for (Layer? child = layer.firstChild; child != null; child = child.nextSibling) {
      if (child is PictureLayer && child.picture != null) canvas.drawPicture(child.picture!);
    }
    final ui.Picture picture = recorder.endRecording();
    try {
      final ui.Image image = await picture.toImage(16, (pixelRatio * 24).ceil());
      try {
        final ByteData? pixels = await image.toByteData(); // crashes here on Impeller GLES
        debugPrint('read ${pixels?.lengthInBytes} bytes');
      } finally {
        image.dispose();
      }
    } finally {
      picture.dispose();
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => MaterialApp(
        home: RepaintBoundary(
          key: _boundary,
          child: Scaffold(
            appBar: AppBar(title: const Text('Readback')),
            body: ListView.builder(itemBuilder: (_, i) => ListTile(title: Text('Row $i'))),
          ),
        ),
      );
}
