import 'package:flutter/scheduler.dart';
import 'package:flutter/widgets.dart';

/// Text with a blurred shadow, rebuilt every frame:
/// - MODE=changing: a counter that changes every frame;
/// - MODE=static: a label whose text never changes, only rebuilt;
/// - MODE=both (default): both.
/// BLUR is the shadow's blurRadius (default 4; 0 for a hard shadow).
const mode = String.fromEnvironment('MODE', defaultValue: 'both');
const blur = int.fromEnvironment('BLUR', defaultValue: 4);

void main() => runApp(const Repro());

class Repro extends StatefulWidget {
  const Repro({super.key});

  @override
  State<Repro> createState() => _ReproState();
}

class _ReproState extends State<Repro> with SingleTickerProviderStateMixin {
  late final Ticker _ticker;
  int _frame = 0;

  @override
  void initState() {
    super.initState();
    _ticker = createTicker((_) => setState(() => _frame++))..start();
  }

  @override
  void dispose() {
    _ticker.dispose();
    super.dispose();
  }

  static const _style = TextStyle(
    fontSize: 24,
    color: Color(0xFFFFFFFF),
    shadows: [
      Shadow(color: Color(0xE6000000), blurRadius: blur * 1.0),
    ],
  );

  @override
  Widget build(BuildContext context) => Directionality(
    textDirection: TextDirection.ltr,
    child: ColoredBox(
      color: const Color(0xFF806040),
      child: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (mode != 'static') Text('frame $_frame', style: _style),
            if (mode != 'changing') const Text('STATIC LABEL', style: _style),
          ],
        ),
      ),
    ),
  );
}
