import 'dart:ui' show SemanticsFlag;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';

SemanticsNode textFieldNode(WidgetTester tester) {
  SemanticsNode? found;
  bool visit(SemanticsNode node) {
    if (node.getSemanticsData().hasFlag(SemanticsFlag.isTextField)) {
      found = node;
      return false;
    }
    node.visitChildren(visit);
    return found == null;
  }

  visit(tester.binding.pipelineOwner.semanticsOwner!.rootSemanticsNode!);
  return found!;
}

Future<void> refocus(WidgetTester tester, FocusNode focusNode) async {
  focusNode.requestFocus();
  await tester.pump();
  focusNode.unfocus();
  await tester.pump();
  await tester.pump();
  focusNode.requestFocus(); // the selection is now valid: collapsed at the end
  await tester.pump();
  await tester.pump(const Duration(seconds: 2));
}

void main() {
  testWidgets('EditableText: focus regained with a valid selection', (tester) async {
    final semantics = tester.ensureSemantics();
    final focusNode = FocusNode();
    await tester.pumpWidget(MaterialApp(
      home: Material(
        child: EditableText(
          controller: TextEditingController(text: 'draft'),
          focusNode: focusNode,
          style: const TextStyle(fontSize: 14),
          cursorColor: Colors.black,
          backgroundCursorColor: Colors.grey,
        ),
      ),
    ));
    await refocus(tester, focusNode);

    expect(focusNode.hasFocus, isTrue);
    expect(tester.allRenderObjects.whereType<RenderEditable>().single.hasFocus, isTrue); // fails: false
    expect(textFieldNode(tester).getSemanticsData().hasFlag(SemanticsFlag.isFocused), isTrue); // fails: false
    semantics.dispose();
  });

  testWidgets('TextField: focus regained with a valid selection', (tester) async {
    final semantics = tester.ensureSemantics();
    final focusNode = FocusNode();
    await tester.pumpWidget(MaterialApp(
      home: Material(
        child: TextField(controller: TextEditingController(text: 'draft'), focusNode: focusNode),
      ),
    ));
    await refocus(tester, focusNode);

    expect(focusNode.hasFocus, isTrue);
    expect(tester.allRenderObjects.whereType<RenderEditable>().single.hasFocus, isTrue); // passes
    expect(textFieldNode(tester).getSemanticsData().hasFlag(SemanticsFlag.isFocused), isTrue); // passes
    semantics.dispose();
  });
}
