### Steps to reproduce


1. With an unmodified Flutter 3.47.8 stable SDK, create a Flutter app (`flutter create sweep_gradient_negative_angles`). Put the complete example below in `lib/main.dart`.
2. The example defines gradient **A** (red to blue) and gradient **B** (green to yellow). Both start at `-90°` (`-π/2`, the top of the circle) and end at `360°` (`2π`, the right side after one full turn). Their stored angle span is `450°` clockwise. Only their colors differ.
3. It computes `SweepGradient.lerp(A, B, 0)`. At `t = 0`, **Result** should equal **A**, including its angles. The example paints A, Result, and B on three labeled circles using `BoxDecoration(gradient: ...)`. The overlaid spiral traces each gradient's *stored angles*: its dot marks the start and its arrowhead marks the end. It is a guide to the angle fields, not the shader's color mapping.
4. Run `flutter run -d chrome`. Compare **A** with **Result**, including their angle labels and spiral starts. There is no animation or changing input in this reproduction.

The decisive observation is the `startAngle` mismatch at `t = 0`. The circles also show a visible change in color distribution, while the spiral makes the distinct `-90°` and `0°` starts clear.

```dart
import 'dart:math' as math;

import 'package:flutter/material.dart';

void main() {
  const a = SweepGradient(
    startAngle: -math.pi / 2,
    endAngle: 2 * math.pi,
    colors: <Color>[Colors.red, Colors.blue],
  );
  const b = SweepGradient(
    startAngle: -math.pi / 2,
    endAngle: 2 * math.pi,
    colors: <Color>[Colors.green, Colors.yellow],
  );
  final result = SweepGradient.lerp(a, b, 0)!;

  runApp(
    MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: const Text('SweepGradient.lerp at t = 0')),
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              const Text('A and B use -90° to 360°; only their colors differ.'),
              const Text('At t = 0, Result = lerp(A, B, 0) should match A.'),
              const Text(
                'Spiral guide: dot = stored start, arrowhead = stored end.',
              ),
              const SizedBox(height: 24),
              Wrap(
                alignment: WrapAlignment.center,
                spacing: 20,
                runSpacing: 20,
                children: <Widget>[
                  sample('A: red → blue', a),
                  sample('Result: lerp(A, B, 0)', result),
                  sample('B: green → yellow', b),
                ],
              ),
            ],
          ),
        ),
      ),
    ),
  );
}

Widget sample(String label, SweepGradient gradient) => SizedBox(
  width: 240,
  child: Column(
    mainAxisSize: MainAxisSize.min,
    children: <Widget>[
      Text(label),
      const SizedBox(height: 8),
      Container(
        width: 170,
        height: 170,
        decoration: BoxDecoration(shape: BoxShape.circle, gradient: gradient),
        child: CustomPaint(
          painter: AngleSpiralPainter(gradient.startAngle, gradient.endAngle),
        ),
      ),
      const SizedBox(height: 8),
      Text(
        'start ${(gradient.startAngle * 180 / math.pi).round()}°, end ${(gradient.endAngle * 180 / math.pi).round()}°',
      ),
    ],
  ),
);

class AngleSpiralPainter extends CustomPainter {
  const AngleSpiralPainter(this.startAngle, this.endAngle);

  final double startAngle;
  final double endAngle;

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final span = endAngle - startAngle;
    final steps = (span.abs() / (2 * math.pi) * 180).ceil();
    final outerRadius = math.min(size.width, size.height) * 0.4;

    Offset point(double t) {
      final angle = startAngle + span * t;
      final radius = 18 + (outerRadius - 18) * t;
      return center +
          Offset(math.cos(angle) * radius, math.sin(angle) * radius);
    }

    final start = point(0);
    final path = Path()..moveTo(start.dx, start.dy);
    for (var i = 1; i <= steps; i++) {
      final current = point(i / steps);
      path.lineTo(current.dx, current.dy);
    }
    canvas.drawPath(
      path,
      Paint()
        ..color = Colors.white
        ..style = PaintingStyle.stroke
        ..strokeWidth = 7
        ..strokeCap = StrokeCap.round,
    );
    canvas.drawPath(
      path,
      Paint()
        ..color = Colors.black87
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3
        ..strokeCap = StrokeCap.round,
    );

    canvas.drawCircle(start, 5, Paint()..color = Colors.white);
    canvas.drawCircle(start, 3, Paint()..color = Colors.black87);

    final tip = point(1);
    final previous = point(0.99);
    final direction = (tip - previous) / (tip - previous).distance;
    final normal = Offset(-direction.dy, direction.dx);
    final base = tip - direction * 15;
    final arrow = Path()
      ..moveTo(tip.dx, tip.dy)
      ..lineTo((base + normal * 7).dx, (base + normal * 7).dy)
      ..lineTo((base - normal * 7).dx, (base - normal * 7).dy)
      ..close();
    canvas.drawPath(arrow, Paint()..color = Colors.black87);
    canvas.drawPath(
      arrow,
      Paint()
        ..color = Colors.white
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2,
    );
  }

  @override
  bool shouldRepaint(covariant AngleSpiralPainter oldDelegate) =>
      oldDelegate.startAngle != startAngle || oldDelegate.endAngle != endAngle;
}
```


### Expected results

At `t = 0`, **Result** has the same colors and angles as **A**, reports `start -90°, end 360°`, and paints identically. Both spiral dots start at the top (`-90°`); both arrowheads end at the right (`360°`).

### Actual results

**Result** reports `start 0°, end 360°`, reducing the stored span from `450°` to `360°`. Its spiral dot starts at the right (`0°`) instead of the top (`-90°`), and its painted colors differ from **A** despite `t = 0`. No exception is logged.

